import { BrowserRouter, Routes, Route, Link, useNavigate, useParams, useLocation, Navigate } from 'react-router-dom';

function Navigation() {
  const location = useLocation();

  const isActive = (path) => location.pathname === path;

  return (
    <nav className="navigation">
      <Link to="/" className={isActive('/') ? 'active' : ''}>Home</Link>
      <Link to="/about" className={isActive('/about') ? 'active' : ''}>About</Link>
      <Link to="/users" className={isActive('/users') ? 'active' : ''}>Users</Link>
    </nav>
  );
}

function Home() {
  return <h1>Welcome Home</h1>;
}

function About() {
  return <h1>About Us</h1>;
}

function Users() {
  const navigate = useNavigate();
  const users = [{ id: 1, name: 'Alice' }, { id: 2, name: 'Bob' }];

  return (
    <div>
      <h1>Users</h1>
      <ul>
        {users.map(user => (
          <li key={user.id} onClick={() => navigate(`/users/${user.id}`)} style={{ cursor: 'pointer' }}>
            {user.name}
          </li>
        ))}
      </ul>
    </div>
  );
}

function UserDetail() {
  const { id } = useParams();
  const navigate = useNavigate();

  return (
    <div>
      <h1>User {id}</h1>
      <button onClick={() => navigate(-1)}>Go Back</button>
    </div>
  );
}

function ProtectedRoute({ children }) {
  const isAuthenticated = false; // Replace with real auth check

  if (!isAuthenticated) {
    return <Navigate to="/login" replace />;
  }

  return children;
}

function NotFound() {
  const navigate = useNavigate();

  return (
    <div>
      <h1>404 - Page Not Found</h1>
      <p>The page you are looking for does not exist.</p>
      <button onClick={() => navigate('/')}>Go Home</button>
    </div>
  );
}

function AppRouter() {
  return (
    <BrowserRouter>
      <Navigation />
      <main>
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/about" element={<About />} />
          <Route path="/users" element={<Users />} />
          <Route path="/users/:id" element={<UserDetail />} />
          <Route
            path="/dashboard"
            element={<ProtectedRoute><h1>Dashboard</h1></ProtectedRoute>}
          />
          <Route path="*" element={<NotFound />} />
        </Routes>
      </main>
    </BrowserRouter>
  );
}
